// Uma consulta por unidade ao ED1 (agendados da agenda). Pedido de Exame e ED2
// dependem do ED1 e são montados depois, em "Monta consultas por empresa".
// Período: de hoje até o próximo dia útil (na sexta, até segunda).
const DIAS_UTEIS_A_FRENTE = 1;

const FUSO = 'America/Sao_Paulo';
const hojeIso = () => new Intl.DateTimeFormat('en-CA', { timeZone: FUSO, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const paraData = (iso) => { const [a, m, d] = iso.split('-').map(Number); return new Date(Date.UTC(a, m - 1, d)); };
const somarDias = (iso, n) => { const d = paraData(iso); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };
const br = (iso) => { const [a, m, d] = iso.split('-'); return `${d}/${m}/${a}`; };

const hoje = hojeIso();
let fim = hoje;
for (let uteis = 0; uteis < DIAS_UTEIS_A_FRENTE;) {
    fim = somarDias(fim, 1);
    const ds = paraData(fim).getUTCDay();
    if (ds !== 0 && ds !== 6) uteis++;
}

const integracoes = $('Integração SOC').all().map((i) => i.json).filter((u) => u && u.unidade_id && u.codigo_usuario_agenda);
const exportaDados = $('Exporta Dados').all().map((i) => i.json).filter((e) => e && e.unidade_id && e.ativo !== false);

const saida = [];
for (const u of integracoes) {
    const ed = (identificador) => exportaDados.find((e) => e.unidade_id === u.unidade_id && e.identificador === identificador);
    const base = {
        unidade_id: u.unidade_id,
        data_inicio: hoje,
        data_fim: fim,
        empresa_principal: u.empresa_principal,
        ws_url: u.ws_url,
        ws_username: u.ws_username,
        ws_senha: u.ws_senha,
        ws_security: u.ws_security,
    };

    const ed1 = ed('agendados_agenda');
    if (ed1) {
        saida.push({
            json: {
                ...base,
                etapa: 'ED1',
                ed_codigo: ed1.codigo,
                ed_chave: ed1.chave,
                parametros: {
                    tipoSaida: 'xml', // o ED1 não aceita json (só html, txt, csv e xml)
                    codigoUsuarioAgenda: String(u.codigo_usuario_agenda),
                    dataInicial: br(hoje),
                    dataFinal: br(fim),
                },
            },
        });
    }
}

// Sem ED1 configurado em nenhuma unidade: ainda grava a falha no log.
if (!saida.length) return [{ json: { sem_consultas: true } }];
return saida;

// Dados do WS-Security, gerados logo antes de cada chamada (o timestamp vale 1 minuto).
// PasswordDigest = Base64(SHA1(nonce + created + chave de acesso)); o SHA1 é feito
// no node Crypto a seguir, a partir do binário digestInput.
return $input.all().map((item) => {
    const j = item.json;

    const nonceBytes = Buffer.from(Array.from({ length: 16 }, () => Math.floor(Math.random() * 256)));
    const agora = new Date();
    const tokenCreated = agora.toISOString();
    const timestampCreated = tokenCreated.replace(/\.\d{3}Z$/, 'Z');
    const expires = new Date(agora.getTime() + 60000).toISOString().replace(/\.\d{3}Z$/, 'Z');
    const wsId = Math.random().toString(36).substring(2, 18).toUpperCase();

    const digestInput = Buffer.concat([
        nonceBytes,
        Buffer.from(tokenCreated, 'utf8'),
        Buffer.from(String(j.ws_senha ?? '').trim(), 'utf8'),
    ]);

    return {
        json: {
            ...j,
            nonce: nonceBytes.toString('base64'),
            tokenCreated,
            timestampCreated,
            expires,
            wsId,
        },
        binary: {
            digestInput: {
                data: digestInput.toString('base64'),
                mimeType: 'application/octet-stream',
                fileName: 'digest-input.bin',
            },
        },
    };
});

// Envelope SOAP do Exporta Dados com o cabeçalho WS-Security.
// $json.data = PasswordDigest calculado pelo node Crypto.
// Segredos (chave de acesso e chave do ED) não seguem para os próximos nodes.
const escaparXml = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

return $input.all().map((item) => {
    const {
        ws_senha, ed_chave, nonce, tokenCreated, timestampCreated, expires, wsId, data: passwordDigest,
        ...meta
    } = item.json;

    let erro_config = null;
    if (!meta.ws_url) erro_config = 'URL do web service não informada em Integrações';
    else if (!meta.ed_codigo || !ed_chave) erro_config = 'Exporta Dados sem código ou chave em Integrações';
    else if (meta.ws_security !== false && (!meta.ws_username || !ws_senha)) erro_config = 'Informe o username e a chave de acesso em Integrações';

    const cabecalho = meta.ws_security === false
        ? '<soapenv:Header/>'
        : '<soapenv:Header>'
            + '<wsse:Security soapenv:mustUnderstand="1" xmlns:wsse="http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-wssecurity-secext-1.0.xsd" xmlns:wsu="http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-wssecurity-utility-1.0.xsd">'
            + `<wsu:Timestamp wsu:Id="TS-${wsId}"><wsu:Created>${timestampCreated}</wsu:Created><wsu:Expires>${expires}</wsu:Expires></wsu:Timestamp>`
            + `<wsse:UsernameToken wsu:Id="UsernameToken-${wsId}">`
            + `<wsse:Username>${escaparXml(String(meta.ws_username ?? '').trim())}</wsse:Username>`
            + `<wsse:Password Type="http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-username-token-profile-1.0#PasswordDigest">${passwordDigest}</wsse:Password>`
            + `<wsse:Nonce EncodingType="http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-soap-message-security-1.0#Base64Binary">${nonce}</wsse:Nonce>`
            + `<wsu:Created>${tokenCreated}</wsu:Created>`
            + '</wsse:UsernameToken></wsse:Security></soapenv:Header>';

    const parametros = JSON.stringify({
        empresa: String(meta.empresa_principal ?? ''),
        codigo: String(meta.ed_codigo ?? '').trim(),
        chave: String(ed_chave ?? '').trim(),
        tipoSaida: 'json',
        ...(meta.parametros || {}),
    });

    const soapXml = '<soapenv:Envelope xmlns:soapenv="http://schemas.xmlsoap.org/soap/envelope/" xmlns:ser="http://services.soc.age.com/">'
        + cabecalho
        + '<soapenv:Body><ser:exportaDadosWs><arg0>'
        + `<parametros>${escaparXml(parametros)}</parametros>`
        + '</arg0></ser:exportaDadosWs></soapenv:Body></soapenv:Envelope>';

    return {
        json: {
            ...meta,
            erro_config,
            // Com erro de configuração, a URL vazia faz o HTTP falhar e a leitura registra o motivo.
            ws_url: erro_config ? '' : String(meta.ws_url).trim(),
            soapXml,
        },
    };
});

// Lê a resposta do Exporta Dados (modo: uma vez por item).
// Monta SOAP é trocado pelo nome do node "Monta SOAP" da etapa.
// O retorno pode vir em json, xml ou csv, conforme o tipoSaida do ED.
const meta = $('Monta SOAP').item.json;
const base = {
    unidade_id: meta.unidade_id,
    etapa: meta.etapa,
    chave_funcionario: meta.chave_funcionario ?? null,
    codigo_empresa: meta.codigo_empresa ?? null,
};
const falhou = (erro) => ({ json: { ...base, ok: false, erro, dados: [] } });

const desescapar = (t) => String(t ?? '')
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;/g, "'")
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
    .replace(/&amp;/g, '&');
const tag = (xml, nome) => {
    const m = xml.match(new RegExp(`<(?:[\\w-]+:)?${nome}>([\\s\\S]*?)</(?:[\\w-]+:)?${nome}>`));
    if (!m) return null;
    const cdata = m[1].match(/^<!\[CDATA\[([\s\S]*)\]\]>$/);
    return cdata ? cdata[1] : desescapar(m[1]);
};

// XML: cada elemento que só tem campos simples é um registro.
function registrosXml(xml) {
    const limpo = xml.replace(/<\?xml[^>]*\?>/g, '').replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, (_, t) => t.replace(/</g, '&lt;'));
    const registros = [];
    const reRegistro = /<([\w.-]+)>((?:\s*<([\w.-]+)(?:\s*\/>|>[^<]*<\/\3>))+)\s*<\/\1>/g;
    let m;
    while ((m = reRegistro.exec(limpo))) {
        const registro = {};
        const reCampo = /<([\w.-]+)(?:\s*\/>|>([^<]*)<\/\1>)/g;
        let c;
        while ((c = reCampo.exec(m[2]))) registro[c[1]] = desescapar(c[2] ?? '').trim();
        registros.push(registro);
    }
    return registros;
}

// CSV: primeira linha é o cabeçalho; separador ";" ou ",".
function registrosCsv(texto) {
    const linhas = texto.split(/\r?\n/).filter((l) => l.trim());
    if (linhas.length < 2) return [];
    const sep = (linhas[0].match(/;/g) || []).length >= (linhas[0].match(/,/g) || []).length ? ';' : ',';
    const limpar = (v) => String(v ?? '').replace(/^"|"$/g, '').trim();
    const cabecalho = linhas[0].split(sep).map(limpar);
    return linhas.slice(1).map((linha) => {
        const valores = linha.split(sep);
        return Object.fromEntries(cabecalho.map((h, i) => [h, limpar(valores[i])]));
    });
}

if (meta.erro_config) return falhou(meta.erro_config);
if ($json.error) {
    const e = $json.error;
    return falhou(String(e.message ?? e.description ?? JSON.stringify(e)));
}

const bruto = $json.data ?? $json.body ?? $json;
if (typeof bruto !== 'string') {
    return falhou('Resposta do HTTP em formato inesperado: deixe o "Response Format" do node HTTP no padrão');
}
const xml = bruto;

const falhaSoap = tag(xml, 'faultstring');
if (falhaSoap) return falhou(falhaSoap);
if (String(tag(xml, 'erro') ?? '').trim() === 'true') return falhou(tag(xml, 'mensagemErro') || 'Erro no Exporta Dados');

const retorno = (tag(xml, 'retorno') ?? '').trim();
if (!retorno) return { json: { ...base, ok: true, dados: [] } };

try {
    let dados;
    if (retorno.startsWith('[') || retorno.startsWith('{')) dados = JSON.parse(retorno);
    else if (retorno.startsWith('<')) dados = registrosXml(retorno);
    else dados = registrosCsv(retorno);
    return { json: { ...base, ok: true, dados: Array.isArray(dados) ? dados : [dados] } };
} catch (e) {
    return falhou(`Resposta inválida do SOC: ${e.message}`);
}

