//  - Pedido de Exame: uma por empresa com agendado (o parâmetro "empresa" é o
//    código da empresa cliente, não o da principal); traz o sequencial da ficha;
//  - ED2 (agendamentos futuros do funcionário): uma por funcionário com
//    agendamento em data futura que ainda não tem horário no banco.
const MAX_CONSULTAS_PEDIDO = 200;
const MAX_CONSULTAS_ED2 = 300;
const DIAS_PEDIDO_ATRAS = 1;
// Pedido de Exame: faixa de códigos de funcionário (todos os funcionários da empresa).
const FUNCIONARIO_INICIO = '1';
const FUNCIONARIO_FIM = '9999';

const isoDeBr = (txt) => { const m = String(txt || '').trim().match(/^(\d{2})\/(\d{2})\/(\d{4})/); return m ? `${m[3]}-${m[2]}-${m[1]}` : null; };
const paraData = (iso) => { const [a, m, d] = iso.split('-').map(Number); return new Date(Date.UTC(a, m - 1, d)); };
const somarDias = (iso, n) => { const d = paraData(iso); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };
const br = (iso) => { const [a, m, d] = iso.split('-'); return `${d}/${m}/${a}`; };
function campo(obj, ...nomes) {
    const mapa = {};
    for (const k of Object.keys(obj || {})) mapa[k.replace(/\s+/g, '').toUpperCase()] = obj[k];
    for (const n of nomes) {
        const v = mapa[n.replace(/\s+/g, '').toUpperCase()];
        if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
    }
    return null;
}

const resultados = $input.all().map((i) => i.json);
const integracoes = $('Integração SOC').all().map((i) => i.json);
const exportaDados = $('Exporta Dados').all().map((i) => i.json).filter((e) => e && e.unidade_id && e.ativo !== false);
const conhecidos = $('Agendamentos conhecidos').all().map((i) => i.json).filter((a) => a && a.unidade_id && a.horario);
const comHorario = new Set(conhecidos.map((a) => `${a.unidade_id}|${a.data}|${a.codigo_empresa}|${a.codigo_funcionario}`));

const consultaInicial = $('Monta consultas iniciais').first().json;
const hoje = consultaInicial.data_inicio;
const fim = consultaInicial.data_fim;

const pedidos = [];
const ed2s = [];
for (const r of resultados.filter((x) => x.etapa === 'ED1' && x.ok)) {
    const u = integracoes.find((x) => x.unidade_id === r.unidade_id);
    if (!u) continue;
    const comum = {
        unidade_id: r.unidade_id,
        empresa_principal: u.empresa_principal,
        ws_url: u.ws_url,
        ws_username: u.ws_username,
        ws_senha: u.ws_senha,
        ws_security: u.ws_security,
    };
    const edPedido = exportaDados.find((e) => e.unidade_id === r.unidade_id && e.identificador === 'pedido_exame');
    const ed2 = exportaDados.find((e) => e.unidade_id === r.unidade_id && e.identificador === 'agendamentos_funcionario');

    const empresas = new Set();
    const funcionarios = new Set();
    for (const linha of r.dados) {
        const data = isoDeBr(campo(linha, 'DATACOMPROMISSO'));
        const empresa = campo(linha, 'CODIGOEMPRESA');
        const funcionario = campo(linha, 'CODIGOFUNCIONARIO');
        if (!data || !empresa || !funcionario) continue;

        // Pedido de Exame: uma consulta por empresa.
        if (edPedido && hoje && fim && !empresas.has(empresa) && pedidos.length < MAX_CONSULTAS_PEDIDO) {
            empresas.add(empresa);
            pedidos.push({
                json: {
                    ...comum,
                    etapa: 'PEDIDO',
                    chave_funcionario: null,
                    codigo_empresa: empresa,
                    ed_codigo: edPedido.codigo,
                    ed_chave: edPedido.chave,
                    // Só estes parâmetros (os demais, mesmo vazios, fazem o SOC não devolver nada).
                    parametros: {
                        empresa,
                        funcionarioInicio: FUNCIONARIO_INICIO,
                        funcionarioFim: FUNCIONARIO_FIM,
                        paramData: '1',
                        dataInicio: br(somarDias(hoje, -DIAS_PEDIDO_ATRAS)),
                        dataFim: br(fim),
                    },
                },
            });
        }

        // ED2: só datas futuras e sem horário no banco; uma consulta por funcionário.
        if (!ed2 || !hoje || data <= hoje) continue;
        if (comHorario.has(`${r.unidade_id}|${data}|${empresa}|${funcionario}`)) continue;
        const chave = `${empresa}|${funcionario}`;
        if (funcionarios.has(chave) || ed2s.length >= MAX_CONSULTAS_ED2) continue;
        funcionarios.add(chave);
        ed2s.push({
            json: {
                ...comum,
                etapa: 'ED2',
                chave_funcionario: chave,
                codigo_empresa: empresa,
                ed_codigo: ed2.codigo,
                ed_chave: ed2.chave,
                parametros: {
                    empresaTrabalho: empresa,
                    codigoFuncionario: funcionario,
                    matriculaFuncionario: '',
                    tipoBuscaFuncionario: '1',
                },
            },
        });
    }
}

const saida = [...pedidos, ...ed2s];
return saida.length ? saida : [{ json: { sem_consultas: true } }];

