    });
}

if (meta.erro_config) return falhou(meta.erro_config);
if ($json.error) {
    const e = $json.error;
    return falhou(String(e.message ?? e.description ?? JSON.stringify(e)));
}

const bruto = $json.data ?? $json.body ?? $json;
if (typeof bruto !== 'string') {
    return falhou('Resposta do HTTP em formato inesperado: deixe o "Response Format" do node HTTP no padrão');
}
const xml = bruto;

const falhaSoap = tag(xml, 'faultstring');
if (falhaSoap) return falhou(falhaSoap);
if (String(tag(xml, 'erro') ?? '').trim() === 'true') return falhou(tag(xml, 'mensagemErro') || 'Erro no Exporta Dados');

const retorno = (tag(xml, 'retorno') ?? '').trim();
if (!retorno) return { json: { ...base, ok: true, dados: [] } };

try {
    let dados;
    if (retorno.startsWith('[') || retorno.startsWith('{')) dados = JSON.parse(retorno);
    else if (retorno.startsWith('<')) dados = registrosXml(retorno);
    else dados = registrosCsv(retorno);
    return { json: { ...base, ok: true, dados: Array.isArray(dados) ? dados : [dados] } };
} catch (e) {
    return falhou(`Resposta inválida do SOC: ${e.message}`);
}

// Junta ED1, Pedido de Exame e ED2 e monta uma linha por unidade para
// agendamentos_sincronizacoes (o trigger do banco grava os agendamentos).
const isoDeBr = (txt) => { const m = String(txt || '').trim().match(/^(\d{2})\/(\d{2})\/(\d{4})/); return m ? `${m[3]}-${m[2]}-${m[1]}` : null; };
const hora = (txt) => { const m = String(txt || '').match(/(\d{1,2}):(\d{2})/); return m ? `${m[1].padStart(2, '0')}:${m[2]}` : null; };
function campo(obj, ...nomes) {
    const mapa = {};
    for (const k of Object.keys(obj || {})) mapa[k.replace(/\s+/g, '').toUpperCase()] = obj[k];
    for (const n of nomes) {
        const v = mapa[n.replace(/\s+/g, '').toUpperCase()];
        if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
    }
    return null;
}

const consultas = $('Monta consultas iniciais').all().map((i) => i.json);
const periodo = consultas.find((c) => c.data_inicio) || {};
const iniciais = consultas.some((c) => c.sem_consultas) ? [] : $('Loop consultas').all(0).map((i) => i.json);
let porEmpresa = [];
try {
    porEmpresa = $('Loop por empresa').all(0).map((i) => i.json).filter((r) => r.etapa);
} catch (e) {
    porEmpresa = []; // nenhuma consulta por empresa nesta execução
}
const respostasEd2 = porEmpresa.filter((r) => r.etapa === 'ED2');
const respostasPedido = porEmpresa.filter((r) => r.etapa === 'PEDIDO');

const integracoes = $('Integração SOC').all().map((i) => i.json).filter((u) => u && u.unidade_id && u.codigo_usuario_agenda);
const saida = [];

for (const u of integracoes) {
    const doUnidade = iniciais.filter((r) => r.unidade_id === u.unidade_id);
    const ed1 = doUnidade.find((r) => r.etapa === 'ED1');
    const pedidos = respostasPedido.filter((r) => r.unidade_id === u.unidade_id);
    const erros = [];
    for (const p of pedidos.filter((x) => !x.ok)) erros.push({ etapa: 'Pedido de Exame', empresa: p.codigo_empresa, erro: p.erro });

    // Sem ED1 não grava nada (evita marcar todos como removidos).
    if (!ed1 || !ed1.ok) {
        erros.push({ etapa: 'ED1 agendados_agenda', erro: ed1 ? ed1.erro : 'Exporta Dados agendados_agenda não configurado em Integrações' });
        saida.push({ json: { unidade_id: u.unidade_id, data_inicio: periodo.data_inicio ?? null, data_fim: periodo.data_fim ?? null, itens: null, resumo: null, erros, situacao: 'falha_consulta' } });
        continue;
    }

    // Sequencial da ficha: a da mesma data do agendamento; senão, a mais recente até essa data.
    const fichas = new Map();
    for (const p of pedidos.filter((x) => x.ok).flatMap((x) => x.dados)) {
        const seq = campo(p, 'SEQUENCIAFICHA');
        if (!seq) continue;
        const chave = `${campo(p, 'CODIGOEMPRESA')}|${campo(p, 'CODIGOFUNCIONARIO')}`;
        const lista = fichas.get(chave) || [];
        if (!lista.some((f) => f.seq === seq)) lista.push({ seq, data: isoDeBr(campo(p, 'DATAFICHA', 'DATACRIACAOPEDIDOEXAMES')) });
        fichas.set(chave, lista);
    }
    const fichaDo = (a) => {
        const lista = fichas.get(`${a.codigo_empresa}|${a.codigo_funcionario}`) || [];
        const mesmaData = lista.find((f) => f.data === a.data);
        if (mesmaData) return mesmaData.seq;
        const anteriores = lista.filter((f) => f.data && f.data <= a.data).sort((x, y) => y.data.localeCompare(x.data));
        return anteriores[0]?.seq ?? null;
    };

    const ed2PorFuncionario = new Map(
        respostasEd2.filter((r) => r.unidade_id === u.unidade_id).map((r) => [r.chave_funcionario, r])
    );
    for (const r of ed2PorFuncionario.values()) {
        if (!r.ok) erros.push({ etapa: 'ED2 agendamentos_funcionario', funcionario: r.chave_funcionario, erro: r.erro });
    }

    const itens = [];
    for (const linha of ed1.dados) {
        const data = isoDeBr(campo(linha, 'DATACOMPROMISSO'));
        const codigoEmpresa = campo(linha, 'CODIGOEMPRESA');
        const codigoFuncionario = campo(linha, 'CODIGOFUNCIONARIO');
        if (!data || !codigoEmpresa || !codigoFuncionario) continue;

        const a = {
            data,
            horario: hora(campo(linha, 'DATACOMPROMISSO')),
            codigo_agendamento: null,
            codigo_usuario_agenda: campo(linha, 'CODIGOUSUARIOAGENDA'),
            codigo_empresa: codigoEmpresa,
            nome_empresa: campo(linha, 'NOMEEMPRESA'),
            codigo_funcionario: codigoFuncionario,
            nome: campo(linha, 'NOMEFUNCIONARIO'),
            cpf: (campo(linha, 'CPFFUNCIONARIO') || '').replace(/\D/g, '') || null,
            tipo_compromisso: Number(campo(linha, 'TIPOCOMPROMISSO')) || null,
            sequencial_ficha: null,
            atendido_soc: null,
        };

        const ed2 = ed2PorFuncionario.get(`${codigoEmpresa}|${codigoFuncionario}`);
        if (ed2 && ed2.ok) {
            const doDia = ed2.dados.filter((f) => isoDeBr(campo(f, 'DATA')) === data);
            const nomeAgenda = campo(linha, 'NOMEAGENDA');
            const escolhido = doDia.find((f) => nomeAgenda && campo(f, 'AGENDA') === nomeAgenda) || doDia[0];
            if (escolhido) {
                a.horario = hora(campo(escolhido, 'HORARIO'));
                a.codigo_agendamento = campo(escolhido, 'CODIGOAGENDAMENTO', 'CODIGO AGENDAMENTO');
                const atendido = campo(escolhido, 'ATENDIDO');
                a.atendido_soc = atendido === null ? null : /^(s|sim|true|1)$/i.test(atendido);
            }
        }

        a.sequencial_ficha = fichaDo(a);
        itens.push(a);
    }

    saida.push({
        json: {
            unidade_id: u.unidade_id,
            data_inicio: periodo.data_inicio,
            data_fim: periodo.data_fim,
            itens,
            resumo: {
                agendados: itens.length,
                consultas_ed2: ed2PorFuncionario.size,
                com_horario: itens.filter((i) => i.horario).length,
            },
            erros: erros.length ? erros : null,
            situacao: null,
        },
    });
}

return saida;
